<?php
require __DIR__.'/bootstrap.php';
$checks=0;$check=function($ok,$label)use(&$checks){if(!$ok){throw new RuntimeException('FAIL: '.$label);}$checks++;};
$builder=new SuiteEdge\Migrator\Elementor\DocumentBuilder();$serializer=new SuiteEdge\Migrator\Elementor\Classic\Serializer();
$build=function($raw)use($builder,$serializer){return $serializer->serialize($builder->build($raw));};
$css=function($nodes)use(&$css){$out='';foreach($nodes as$n){if(($n['widgetType']??'')==='html'){$out.=$n['settings']['html'];}$out.=$css($n['elements']);}return$out;};
foreach(['Short','Much longer text with several words']as$text){$data=$build('[et_pb_text background_color="#333537" module_alignment="center"]<p>'.$text.'</p>[/et_pb_text]');$check($data[0]['settings']['_element_custom_width']===['unit'=>'%','size'=>100],'default block width independent of content length');$s=$css($data);$check(strpos($s,'margin-left:auto;margin-right:auto;')!==false&&strpos($s,'margin:auto;')===false,'horizontal alignment does not alter vertical margins');$check(!$builder->warnings,'fully mapped caption does not warn');}
$data=$build('[et_pb_text width="60%" width_tablet="300px" width_phone="80%" max_width="500px" module_alignment="right" module_alignment_tablet="left" module_alignment_phone="center" custom_margin="17px||23px||false|false"]<p>Explicit</p>[/et_pb_text]');$s=$data[0]['settings'];
foreach([''=>[60,'%'],'_tablet'=>[300,'px'],'_mobile'=>[80,'%']]as$suffix=>$expected){$check($s['_element_custom_width'.$suffix]['size']===$expected[0]*1.0&&$s['_element_custom_width'.$suffix]['unit']===$expected[1],'explicit width survives on '.$suffix);}
$s=$css($data);foreach(['margin-left:auto;margin-right:0;','margin-left:0;margin-right:auto;','margin-left:auto;margin-right:auto;','margin-top:17px!important;','margin-bottom:23px!important;','max-width:500px;']as$rule){$check(strpos($s,$rule)!==false,'source constraint retained: '.$rule);}
$data=$build('[et_pb_text width="0px"]Hidden-sized content[/et_pb_text]');$check($data[0]['settings']['_element_custom_width']['size']===0.0,'explicit zero width not replaced by default');
$data=$build('[et_pb_section][et_pb_row][et_pb_column][et_pb_text]Content[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]');$check($data[0]['settings']['background_color']==='#ffffff'&&$data[0]['settings']['background_background']==='classic','default section white source surface');$check(!isset($data[0]['elements'][0]['settings']['background_color']),'rows do not acquire section background defaults');$check(!isset($data[0]['elements'][0]['elements'][0]['settings']['background_color']),'columns remain transparent by default');
foreach(['background_color="#123456"'=>'#123456','background_color="rgba(255,255,255,0)"'=>'rgba(255,255,255,0)','background_color="#ff0000" background_enable_color="off"'=>'#ffffff']as$attrs=>$color){$data=$build('[et_pb_section '.$attrs.' /]');$check($data[0]['settings']['background_color']===$color,'active/inactive/transparent source color preserved');}
$data=$build('[et_pb_section use_background_color_gradient="on" background_color_gradient_start="rgba(0,0,0,.3)" background_color_gradient_end="rgba(0,0,0,.6)" /]');$check(strpos($css($data),'background-color:#ffffff;')!==false&&$data[0]['settings']['background_color']==='rgba(0,0,0,.3)','white solid base kept independently of native alpha gradient');
$data=$build('[et_pb_section background_color="#123456" use_background_color_gradient="on" background_color_gradient_start="rgba(0,0,0,.3)" /]');$check(strpos($css($data),'background-color:#123456;')!==false,'explicit solid base remains below gradient');
$data=$build('[et_pb_section background_color__hover="#123456" use_background_color_gradient="on" background_color_gradient_start="rgba(0,0,0,.3)" /]');$check(strpos($css($data),':hover{background-color:#123456;}')!==false,'source hover surface is not masked by normal gradient base');
$data=$build('[et_pb_section background_color="#123456" background_image="https://example.test/background.jpg" use_background_color_gradient="on" background_color_gradient_overlays_image="on" /]');$check($data[0]['settings']['background_color']==='#123456'&&$data[0]['settings']['background_overlay_background']==='gradient','image gradient overlay and base remain separate');
$data=$build('[et_pb_section background_color="red;position:fixed" use_background_color_gradient="on" /]');$check($data[0]['widgetType']==='shortcode','unsafe gradient surface retained as protected fallback');
echo 'PASS: '.$checks.' block layout and section surface assertions'.PHP_EOL;
